  document.querySelectorAll(".delete-unified-control").forEach(x=>x.onclick=async()=>{await api(`/api/projects/${state.project.id}/constraints/${x.dataset.id}`,{method:"DELETE"});await api(`/api/projects/${state.project.id}/artifacts/control_settings`,{method:"PUT",body:JSON.stringify({content:{card_points:$("#cardPointsEditor").value.trim(),hard_constraints:allCards.filter(item=>String(item.id)!==String(x.dataset.id)).map(item=>`【${scopeText(item)}｜${item.label}】${item.text}`).join("\n"),story_state_detached:true},status:"approved"})});await reload()});
