  const synopsisActions=$("#stageContent .panel-head .action-row"),actionStack=document.createElement("div");actionStack.className="panel-action-stack";synopsisActions.replaceWith(actionStack);actionStack.append(synopsisActions);actionStack.insertAdjacentHTML("beforeend",`<button type="button" class="ghost partial-regenerate" id="regenerateAllMustNotReveal" ${eps.length?'':'disabled'}>局部重新生成</button>`);
