  const save=async()=>{const items=collect(),mainNames=(artifact("characters")?.content?.characters||[]).map(item=>String(item.name||"").trim()).filter(Boolean),seen=new Map();for(const ep of items){const names=[...new Set(String(ep.first_appearance_characters||"").split(/[；;、,，\n]+/).map(x=>x.trim()).filter(x=>x&&!/^(?:无|暂无|没有)$/.test(x)))],invalid=names.filter(name=>!mainNames.includes(name));if(invalid.length){const message=`EP${String(ep.episode_no).padStart(2,"0")} 首次出场人物不在03主要人物中：${invalid.join("、")}`;toast(message);throw new Error(message)}for(const name of names){if(seen.has(name)){const message=`主要人物“${name}”同时标在 EP${String(seen.get(name)).padStart(2,"0")} 和 EP${String(ep.episode_no).padStart(2,"0")} 首次出场`;toast(message);throw new Error(message)}seen.set(name,ep.episode_no)}ep.first_appearance_characters=names.join("；")||"无"}await Promise.all(items.map(ep=>api(`/api/projects/${state.project.id}/episodes/${ep.episode_no}`,{method:"PUT",body:JSON.stringify({title:ep.title,summary:ep.summary,hook:ep.hook,required_plot:ep.required_plot,must_not_reveal:ep.must_not_reveal,first_appearance_characters:ep.first_appearance_characters})})));await api(`/api/projects/${state.project.id}/artifacts/outline`,{method:"PUT",body:JSON.stringify({content:{episodes:items},status:"draft"})})};
