function showTemplateAnalysisProgress(){const dialog=$("#templateReviewDialog"),form=$("#templateReviewForm");let progress=form.querySelector(".template-analysis-progress");if(!progress){progress=document.createElement("div");progress.className="template-analysis-progress";progress.innerHTML=`<div class="template-progress-copy"><strong>正在分析模板</strong><span>0%</span></div><div class="template-progress-track"><i></i></div><p>正在读取 DOCX 内容…</p>`;form.querySelector(".dialog-head").after(progress)}form.classList.add("analyzing");let value=0;const render=()=>{progress.querySelector("span").textContent=`${value}%`;progress.querySelector("i").style.width=`${value}%`;progress.querySelector("p").textContent=value<30?"正在读取 DOCX 内容…":value<65?"正在识别篇幅、场次和剧本格式…":"正在整理为可编辑的模板字段…"};render();clearInterval(templateProgressTimer);templateProgressTimer=setInterval(()=>{value=Math.min(92,value+(value<60?8:3));render()},350);if(!dialog.open)dialog.showModal()}
const templateMidpoint=(min,max)=>Math.round((Number(min)+Number(max))/2);
