const setTemplateRange=(form,prefix,range,fallback)=>{const value=range||fallback;form.elements[`${prefix}_min`].value=value.min;form.elements[`${prefix}_max`].value=value.max;form.elements[`${prefix}_ideal`].value=["novel","script"].includes(prefix)?templateMidpoint(value.min,value.max):(value.ideal??value.average??templateMidpoint(value.min,value.max))};
