  form.elements.name.value=result.name||"";setTemplateRange(form,"novel",format.novelCharacters,{min:1000,ideal:1250,max:1500});setTemplateRange(form,"script",format.targetCharacters,{min:1500,ideal:1750,max:2000});setTemplateRange(form,"scene",format.targetScenes,{min:1,ideal:2,max:3});
