  for(const key of ["episodeHeading","sceneHeading","dialogue","voiceOver","specialSpeaker","action","notes","sampleExcerpt"])form.elements[key].value=format[key]||"";
  form.elements.writingRules.value=(format.writingRules||[]).join("\n");const detected=result.analysis?.detected||{},source=result.analysis?.sourceAnalysis||{};
  const fromDefault=result.source_mode==="default";$("#templateAdvancedReview").classList.toggle("hidden",fromDefault);$("#templateDetectedSummary").textContent=fromDefault?"以当前默认模板为基础。这里只调整小说字数、剧本字数和每集场次；其余格式沿用默认模板。":`已读取 ${result.analysis?.lineCount||0} 行；${detected.hasScriptSample?`识别到 ${source.sampleEpisodes||0} 集剧本样本` : "未识别到明确的 EP 剧本样本"}。下方展示全部格式分析结果；未能确定的字段已用默认值补齐，保存前均可手动修改。`;
