async function renderWorkbench(){if(!state.workbenchMode)return;const root=$("#workbenchContent");try{const data=await api("/api/workbench");if(!state.workbenchMode)return;state.workbench=data;const used=data.running+data.queued,auto=data.concurrencyMode==="auto";root.innerHTML=`<div class="workbench-head"><div><p class="eyebrow">CROSS-PROJECT QUEUE</p><h2>跨项目任务工作台</h2><p>串行关闭时沿用原来的全局排队；开启后允许不同项目并行，同一项目仍只运行一个任务。</p></div><label class="workbench-switch"><span>${data.parallelEnabled?'并行已开启':'并行已关闭'}</span><input id="parallelToggle" type="checkbox" ${data.parallelEnabled?'checked':''}><i></i></label></div><section class="workbench-settings"><div><strong>并发策略</strong><small>${auto?'系统会在 1–3 个并发间自动调节':'固定使用你选择的并发数'}</small></div><select id="workbenchMode" ${data.parallelEnabled?'':'disabled'}><option value="auto" ${auto?'selected':''}>自动调节（推荐）</option><option value="manual" ${auto?'':'selected'}>手动固定</option></select><select id="workbenchLimit" ${data.parallelEnabled&&!auto?'':'disabled'}><option value="1" ${data.concurrencyLimit===1?'selected':''}>同时 1 个</option><option value="2" ${data.concurrencyLimit===2?'selected':''}>同时 2 个</option><option value="3" ${data.concurrencyLimit===3?'selected':''}>同时 3 个</option></select></section><div class="workbench-metrics"><span><b>${data.running}</b> 运行中</span><span><b>${data.queued}</b> 排队中</span><span><b>${data.effectiveConcurrency}</b> 当前并发</span><span><b>${used}/${data.maxTasks}</b> 工作台容量</span></div>${data.parallelEnabled&&auto&&data.adaptiveLimit<3?`<p class="workbench-notice">检测到接口限流或连接压力，已临时降为 ${data.adaptiveLimit} 个并发，稳定后自动恢复。</p>`:""}<div class="workbench-task-list">${data.parallelEnabled?(data.jobs.map(job=>{const total=Math.max(1,Number(job.total)||1),pct=Math.min(100,Math.round(Number(job.progress||0)/total*100)),target=job.target&&job.target!=="all"?` · ${esc(job.target)}`:"";return `<article class="workbench-task"><div class="workbench-task-head"><div><small>${esc(job.project_title)}</small><strong>${esc(workbenchTaskLabels[job.type]||job.type)}${target}</strong></div><span class="${job.status}">${job.status==="running"?'进行中':'排队中'}</span></div><div class="task-history-progress"><span style="width:${pct}%"></span></div><p>${esc(job.message||'等待调度')}</p><footer><small>${pct}% · 耗时 ${formatDuration(jobElapsedMs(job))}</small><button class="ghost workbench-cancel" data-project="${job.project_id}" data-job="${job.id}">取消</button></footer></article>`}).join("")||'<div class="workbench-empty"><strong>当前没有任务</strong><p>进入任意项目提交生成任务后，会在这里统一显示。</p></div>'):'<div class="workbench-empty"><strong>并行模式未开启</strong><p>现在仍按原来的全局 FIFO 顺序逐个执行任务。开启后，最多容纳 10 个跨项目任务。</p></div>'}</div>`;$("#parallelToggle").onchange=async event=>{const enabled=event.target.checked;if(!enabled&&!confirm("确定关闭并行模式吗？\n\n工作台中正在运行和排队的任务会安全中断，并记录到各自项目的任务列表；之后可从项目页面手动继续。")){event.target.checked=true;return}try{await api("/api/workbench",{method:"PUT",body:JSON.stringify({parallel_enabled:enabled})});toast(enabled?"并行模式已开启":"并行任务已安全中断，可回到各项目继续");await renderWorkbench()}catch(error){event.target.checked=!enabled;toast(error.message)}};$("#workbenchMode").onchange=async event=>{await api("/api/workbench",{method:"PUT",body:JSON.stringify({concurrency_mode:event.target.value})});await renderWorkbench()};$("#workbenchLimit").onchange=async event=>{await api("/api/workbench",{method:"PUT",body:JSON.stringify({concurrency_mode:"manual",concurrency_limit:Number(event.target.value)})});await renderWorkbench()};document.querySelectorAll(".workbench-cancel").forEach(button=>button.onclick=async()=>{if(!confirm("确定取消这个任务吗？\n\n已成功保存的阶段内容会保留。"))return;await api(`/api/projects/${button.dataset.project}/jobs/${button.dataset.job}/cancel`,{method:"POST",body:"{}"});await renderWorkbench()})}catch(error){root.innerHTML=`<div class="workbench-empty"><strong>工作台读取失败</strong><p>${esc(error.message)}</p></div>`}}
